(()=>{"use strict";const SCENE_IONO_RADIUS=5.274682153508083;function latLonAltToVector3(latDeg,lonDeg,altKm=0){const phi=(latDeg||0)*(Math.PI/180),lambda=(lonDeg||0)*(Math.PI/180),r=5*(1+Math.max(0,altKm)/6371);return new window.THREE.Vector3(r*Math.cos(phi)*Math.cos(lambda),r*Math.sin(phi),-r*Math.cos(phi)*Math.sin(lambda))}function calculateIpp3D(stationPos3D,satellitePos3D){if(!stationPos3D||!satellitePos3D)return null;const dir=satellitePos3D.clone().sub(stationPos3D).normalize(),b=2*stationPos3D.dot(dir),c=stationPos3D.lengthSq()-SCENE_IONO_RADIUS*SCENE_IONO_RADIUS,discr=b*b-4*c;if(discr<=0)return null;const t=(-b+Math.sqrt(discr))/2;return stationPos3D.clone().add(dir.multiplyScalar(t))}function groundRegion(features,lat,lon){if(!Array.isArray(features))return"Đang tải tên khu vực…";if(!Number.isFinite(lat)||!Number.isFinite(lon))return"--";const inRing=ring=>{let inside=!1;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const[xi,yi]=ring[i],[xj,yj]=ring[j];yi>lat!=yj>lat&&lon<(xj-xi)*(lat-yi)/(yj-yi)+xi&&(inside=!inside)}return inside};for(const feature of features){const geometry=feature.geometry;let polygons=[];if((geometry==null?void 0:geometry.type)==="Polygon"?polygons=[geometry.coordinates]:(geometry==null?void 0:geometry.type)==="MultiPolygon"&&(polygons=geometry.coordinates),polygons.some(rings=>rings[0]&&inRing(rings[0])&&!rings.slice(1).some(inRing))){const properties=feature.properties||{};return properties.name_vi||properties.ADMIN||properties.name||properties.NAME||"Đất liền"}}return"Biển / đại dương"}function surfaceViewFromRay(position,direction,fov,height){const b=position.x*direction.x+position.y*direction.y+position.z*direction.z,c=position.x**2+position.y**2+position.z**2-5**2,discriminant=b*b-c;if(discriminant<0||height<=0)return null;const distance=-b-Math.sqrt(discriminant);if(distance<=0)return null;const x=position.x+direction.x*distance,y=position.y+direction.y*distance,z=position.z+direction.z*distance,lat=Math.max(-85,Math.min(85,Math.asin(Math.max(-1,Math.min(1,y/5)))*180/Math.PI)),lng=Math.atan2(-z,x)*180/Math.PI,metersPerPixel=distance*6371/5*2e3*Math.tan(fov*Math.PI/360)/height,zoom=Math.log2(156543.03392*Math.cos(lat*Math.PI/180)/metersPerPixel);return{lat,lng,zoom}}window.Globe3DMath={RE_EARTH_KM:6371,SCENE_EARTH_RADIUS:5,H_IONO_KM:350,SCENE_IONO_RADIUS,latLonAltToVector3,calculateIpp3D,groundRegion,surfaceViewFromRay,shouldEnterGlobe:zoom=>Number.isFinite(zoom)&&zoom<=2}})();
